"""Administrator product-image library page."""


def product_image_page():
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="color-scheme" content="light dark"><title>产品图片库</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,"Microsoft YaHei",sans-serif;color:#172033;background:#f5f7fb}
body{margin:0;padding:28px}.page{max-width:1120px;margin:auto}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:22px}.eyebrow{font-size:12px;color:#67728b;letter-spacing:.08em}.top h1{margin:5px 0;font-size:28px}.top p{margin:0;color:#667087}.card{background:#fff;border:1px solid #e4e8f1;border-radius:18px;padding:20px;box-shadow:0 12px 35px #1e2c4b0b;margin-bottom:18px}.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:18px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field{display:grid;gap:6px}.field.full{grid-column:1/-1}.field label{font-size:12px;color:#69748b}.field input,.field textarea,.field select{width:100%;box-sizing:border-box;border:1px solid #d8deea;border-radius:10px;padding:10px;font:inherit;background:#fff;color:#172033}.field textarea{min-height:80px;resize:vertical}.actions{display:flex;gap:8px;align-items:center;margin-top:14px}.button{border:0;border-radius:10px;padding:10px 15px;background:#365eea;color:#fff;font-weight:700;cursor:pointer}.button.secondary{background:#edf1fb;color:#33405d}.button.danger{background:#fbe9eb;color:#b4293b}.notice{font-size:13px;color:#5c6984}.notice.error{color:#b4293b}.assets{display:grid;gap:10px}.asset{display:grid;grid-template-columns:96px minmax(0,1fr) auto;gap:14px;align-items:center;padding:12px;border:1px solid #e5e9f0;border-radius:14px}.asset img{width:96px;height:72px;object-fit:cover;border-radius:10px;background:#eef2f8}.asset h3{margin:0 0 5px;font-size:15px}.asset-icon{display:inline-grid;place-items:center;width:22px;height:22px;margin-right:6px;border-radius:7px;background:#eaf0ff;color:#365eea;font-size:13px;vertical-align:-2px}.asset p{margin:3px 0;color:#6b758a;font-size:12px}.tags{display:flex;flex-wrap:wrap;gap:5px}.tag{font-size:11px;padding:3px 7px;border-radius:99px;background:#eef2ff;color:#3a56af}.status{font-size:11px;padding:4px 7px;border-radius:99px;background:#eaf8ef;color:#247747}.status.off{background:#f2f3f5;color:#70798b}.asset-actions{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.asset-actions button{border:1px solid #d8deea;border-radius:8px;background:#f7f9fd;color:#40506f;padding:6px 8px;cursor:pointer;font-size:11px}.empty{padding:24px;text-align:center;color:#7a8497;border:1px dashed #d8deea}@media(max-width:800px){body{padding:15px}.grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.asset{grid-template-columns:70px minmax(0,1fr)}.asset img{width:70px;height:60px}.asset .actions{grid-column:1/-1}}
</style></head><body><main class="page">
<header class="top"><div><div class="eyebrow">AI SALES WORKSPACE</div><h1>产品图片库</h1><p>为产品名称、SKU、别名和标签绑定可由 AI 自动发送的图片，所有图片保存在面板私有数据卷。</p></div><a class="button secondary" href="/">返回工作台</a></header>
<section class="grid"><div class="card"><h2>全局自动发送</h2><p class="notice">开启后，所有聊天都使用同一套产品图片规则；关闭后 AI 只会发送文字。</p><form id="settingsForm"><div class="form-grid"><div class="field"><label for="autoSend">自动发送</label><select id="autoSend"><option value="1">开启</option><option value="0">关闭</option></select></div><div class="field"><label for="dailyLimit">每日上限</label><input id="dailyLimit" type="number" min="1" max="1000" required></div><div class="field"><label for="confidenceThreshold">匹配置信度阈值</label><input id="confidenceThreshold" type="number" min="0" max="1" step="0.01" required></div><div class="field"><label for="cooldownSeconds">客户冷却秒数</label><input id="cooldownSeconds" type="number" min="0" max="2592000" required></div><div class="field"><label><input id="customerImageRecognition" type="checkbox">启用客户图片识别</label></div><div class="field"><label><input id="chatProductImage" type="checkbox">启用聊天主动产品图片</label></div><div class="field"><label><input id="marketingProductImage" type="checkbox">启用营销产品图片</label></div><div class="field"><label><input id="shadowMode" type="checkbox">影子模式（只记录不发送）</label></div><div class="field"><label><input id="globalKillSwitch" type="checkbox">全局停止产品图片</label></div></div><div class="actions"><button class="button" type="submit">保存全局设置</button><span id="settingsNotice" class="notice" role="status"></span></div></form></div>
<div class="card"><h2>上传图片</h2><form id="uploadForm"><div class="form-grid"><div class="field"><label for="title">标题</label><input id="title" required maxlength="200"></div><div class="field"><label for="tags">产品标签</label><input id="tags" placeholder="例如：IPTV, Premium" required></div><div class="field"><label for="productName">产品名称</label><input id="productName" maxlength="200" placeholder="例如：G5 Plus"></div><div class="field"><label for="sku">SKU</label><input id="sku" maxlength="120" placeholder="例如：G5-PLUS"></div><div class="field"><label for="productId">产品 ID</label><input id="productId" placeholder="产品目录 ID"></div><div class="field"><label for="variant">变体</label><input id="variant" placeholder="例如 red"></div><div class="field"><label for="role">图片角色</label><select id="role"><option value="primary">主图</option><option value="reference">参考图</option><option value="marketing">营销图</option></select></div><div class="field"><label><input id="allowVisual" type="checkbox" checked>允许视觉匹配</label></div><div class="field"><label><input id="allowAuto" type="checkbox" checked>允许自动发送</label></div><div class="field full"><label for="aliases">产品别名</label><input id="aliases" placeholder="例如：IPTV Pro, 高级版"></div><div class="field full"><label for="caption">说明模板</label><textarea id="caption" maxlength="4096" placeholder="可选，支持 {product_tag}"></textarea></div><div class="field full"><label for="image">图片（JPG / PNG / WebP，最大 10MB）</label><input id="image" type="file" accept="image/jpeg,image/png,image/webp" required></div></div><div class="actions"><button class="button" type="submit">上传并绑定</button><span id="uploadNotice" class="notice" role="status"></span></div></form></div></section>
<section class="card"><h2>产品目录</h2><form id="productForm"><div class="form-grid"><div class="field"><label for="catalogKey">产品标识</label><input id="catalogKey" required maxlength="64" pattern="[a-z0-9][a-z0-9_-]{1,63}"></div><div class="field"><label for="catalogName">产品名称</label><input id="catalogName" required maxlength="200"></div><div class="field"><label for="catalogSku">SKU</label><input id="catalogSku" maxlength="120"></div><div class="field"><label for="catalogAliases">别名（逗号分隔）</label><input id="catalogAliases"></div><div class="field full"><label for="catalogDescription">产品介绍</label><textarea id="catalogDescription" maxlength="4000"></textarea></div><div class="field"><label><input id="catalogAiImage" type="checkbox" checked>允许 AI 图片</label></div><div class="field"><label><input id="catalogMarketingImage" type="checkbox" checked>允许营销图片</label></div></div><div class="actions"><button class="button" type="submit">保存产品</button><button id="catalogReset" class="button secondary" type="button">清空</button><span id="catalogNotice" class="notice" role="status"></span></div></form><div id="catalogItems" class="assets" style="margin-top:12px"></div></section>
<section class="card"><h2>匹配诊断（不会发送 WhatsApp）</h2><form id="matchForm" class="actions"><input id="matchProduct" placeholder="候选产品 ID"><input id="matchImage" type="file" accept="image/jpeg,image/png,image/webp" required><button class="button secondary" type="submit">测试匹配</button><span id="matchNotice" class="notice" role="status"></span></form></section><section class="card"><div class="top"><div><h2>图片资产</h2><p class="notice">按产品名称、SKU、别名或标签精确匹配；同一优先级有多个候选时不会自动发送。</p></div><div class="actions"><input id="tagFilter" placeholder="按标签筛选" aria-label="按标签筛选"><input id="productSearch" placeholder="搜索产品 / SKU / 别名" aria-label="搜索产品"><button id="refresh" class="button secondary" type="button">刷新</button></div></div><div id="assets" class="assets"><div class="empty">正在读取图片库…</div></div></section>
<section class="card"><h2>标签管理</h2><form id="tagForm" class="actions"><input id="newTag" placeholder="新标签名称" required maxlength="120"><button class="button" type="submit">新增标签</button><span id="tagNotice" class="notice" role="status"></span></form><div id="tagList" class="tags" style="margin-top:12px"></div></section>
</main><script>
(()=>{'use strict';
const $=id=>document.getElementById(id); let csrf='';
async function ensureCsrf(){if(csrf)return csrf;const r=await fetch('/api/security/csrf',{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.message||'安全校验不可用');csrf=d.csrf_token||'';return csrf;}
async function api(url,options={}){const headers=new Headers(options.headers||{});if(options.method&&options.method!=='GET'){headers.set('X-CSRF-Token',await ensureCsrf());}const r=await fetch(url,{...options,headers,credentials:'same-origin',cache:'no-store'});const type=r.headers.get('content-type')||'';const d=type.includes('application/json')?await r.json():await r.text();if(!r.ok)throw Error(d.message||'请求失败');return d;}
function tagNode(tag){const e=document.createElement('span');e.className='tag';e.textContent=tag.display_name||tag.tag_key;return e;}
function renderTags(items){const root=$('tagList');root.replaceChildren();(items||[]).forEach(item=>root.append(tagNode(item)));if(!items||!items.length){const e=document.createElement('span');e.className='notice';e.textContent='暂无标签';root.append(e);}}
function renderAssets(items){const root=$('assets');root.replaceChildren();if(!items||!items.length){const e=document.createElement('div');e.className='empty';e.textContent='暂无图片资产';root.append(e);return;}items.forEach(item=>{const row=document.createElement('article');row.className='asset';const img=document.createElement('img');img.alt=item.title;img.loading='lazy';img.src='/api/product-images/'+encodeURIComponent(item.asset_id)+'/preview';const body=document.createElement('div');const h=document.createElement('h3');const icon=document.createElement('span');icon.className='asset-icon';icon.setAttribute('aria-hidden','true');icon.textContent='▣';h.append(icon,document.createTextNode(item.title));body.append(h);const p=document.createElement('p');p.textContent=(item.mime_type||'')+' · '+item.width+'×'+item.height+' · '+item.byte_size+' bytes';body.append(p);const metadata=document.createElement('p');metadata.textContent=[item.product_name,item.sku].filter(Boolean).join(' · ');if(metadata.textContent)body.append(metadata);const tags=document.createElement('div');tags.className='tags';(item.tags||[]).forEach(tag=>tags.append(tagNode(tag)));(item.aliases||[]).forEach(alias=>{const e=document.createElement('span');e.className='tag';e.textContent=alias;tags.append(e);});body.append(tags);const status=document.createElement('span');status.className='status'+(item.active?'':' off');status.textContent=item.active?'启用':'已停用';const actions=document.createElement('div');actions.className='asset-actions';const toggle=document.createElement('button');toggle.type='button';toggle.textContent=item.active?'停用':'启用';toggle.addEventListener('click',async()=>{try{await api('/api/product-images/'+encodeURIComponent(item.asset_id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:!item.active})});await load();}catch(err){$('uploadNotice').textContent=err.message;}});const primary=document.createElement('button');primary.type='button';primary.textContent='设为主图';primary.disabled=!(item.tags||[]).length;primary.addEventListener('click',async()=>{const tag=item.tags&&item.tags[0];if(!tag)return;try{await api('/api/product-images/'+encodeURIComponent(item.asset_id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({tag_updates:[{tag_key:tag.tag_key,is_primary:true}]})});await load();}catch(err){$('uploadNotice').textContent=err.message;}});const priority=document.createElement('button');priority.type='button';priority.textContent='保存优先级';priority.addEventListener('click',async()=>{const tag=item.tags&&item.tags[0];if(!tag)return;const value=window.prompt('优先级',String(tag.priority??100));if(value===null)return;const number=Number(value);if(!Number.isInteger(number)||number<0||number>1000000){$('uploadNotice').textContent='优先级必须是 0 至 1000000 的整数';return;}try{await api('/api/product-images/'+encodeURIComponent(item.asset_id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({tag_updates:[{tag_key:tag.tag_key,priority:number}]})});await load();}catch(err){$('uploadNotice').textContent=err.message;}});const remove=document.createElement('button');remove.type='button';remove.textContent='软删除';remove.addEventListener('click',async()=>{if(!window.confirm('确认停用这张图片吗？'))return;try{await api('/api/product-images/'+encodeURIComponent(item.asset_id),{method:'DELETE'});await load();}catch(err){$('uploadNotice').textContent=err.message;}});actions.append(toggle,primary,priority,remove);row.append(img,body,status,actions);root.append(row);});}
function renderCatalog(items){const root=$('catalogItems');root.replaceChildren();(items||[]).forEach(item=>{const row=document.createElement('article');row.className='asset';const body=document.createElement('div');const h=document.createElement('h3');h.textContent=(item.product_name||item.product_key||'未命名产品')+' · '+(item.sku||'无 SKU');body.append(h);const p=document.createElement('p');p.textContent=(item.description||'暂无介绍');body.append(p);const state=document.createElement('span');state.className='status'+(item.active?'':' off');state.textContent=item.active?'启用':'已停用';const actions=document.createElement('div');actions.className='asset-actions';const edit=document.createElement('button');edit.type='button';edit.textContent='编辑';edit.addEventListener('click',()=>{editingProduct=item.product_id;$('catalogKey').value=item.product_key;$('catalogName').value=item.product_name;$('catalogSku').value=item.sku||'';$('catalogAliases').value=(item.aliases||[]).join(',');$('catalogDescription').value=item.description||'';$('catalogAiImage').checked=item.allow_ai_image_send!==false;$('catalogMarketingImage').checked=item.allow_marketing_image_send!==false;});const remove=document.createElement('button');remove.type='button';remove.textContent='停用';remove.disabled=!item.active;remove.addEventListener('click',async()=>{try{await api('/api/product-catalog/'+encodeURIComponent(item.product_id),{method:'DELETE'});await loadCatalog();}catch(err){$('catalogNotice').textContent=err.message;}});actions.append(edit,remove);row.append(body,state,actions);root.append(row);});if(!items||!items.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='暂无产品';root.append(empty);}}
let editingProduct='';
async function loadCatalog(){const data=await api('/api/product-catalog?include_inactive=1');renderCatalog(data.items);}
async function load(){const filter=encodeURIComponent($('tagFilter').value.trim());const product=encodeURIComponent($('productSearch').value.trim());const query='&include_inactive=1'+(filter?'&tag='+filter:'')+(product?'&product='+product:'');const [assets,tags,settings]=await Promise.all([api('/api/product-images?'+query.slice(1)),api('/api/product-tags'),api('/api/product-image-settings?session=default')]);renderAssets(assets.items);renderTags(tags.items);$('autoSend').value=settings.auto_send_enabled?'1':'0';$('dailyLimit').value=settings.daily_limit;$('confidenceThreshold').value=String(settings.product_image_confidence_threshold??0.85);$('cooldownSeconds').value=String(settings.product_image_cooldown_seconds??0);$('customerImageRecognition').checked=settings.customer_image_recognition_enabled!==false;$('chatProductImage').checked=settings.chat_product_image_enabled!==false;$('marketingProductImage').checked=settings.marketing_product_image_enabled!==false;$('shadowMode').checked=Boolean(settings.product_image_shadow_mode);$('globalKillSwitch').checked=Boolean(settings.product_image_global_kill_switch);await loadCatalog();}
$('refresh').addEventListener('click',()=>load().catch(e=>{$('uploadNotice').textContent=e.message;}));$('tagFilter').addEventListener('change',()=>load().catch(e=>{$('uploadNotice').textContent=e.message;}));$('productSearch').addEventListener('input',()=>load().catch(e=>{$('uploadNotice').textContent=e.message;}));$('matchForm').addEventListener('submit',async e=>{e.preventDefault();const file=$('matchImage').files[0];if(!file){$('matchNotice').textContent='请选择图片';return;}const form=new FormData();form.set('candidate_product_id',$('matchProduct').value.trim());form.set('image',file);$('matchNotice').textContent='匹配中…';$('matchNotice').classList.remove('error');try{const result=await api('/api/product-image-match-test',{method:'POST',body:form});const count=(result.candidates||[]).length;$('matchNotice').textContent=result.status==='MATCHED'?('找到 '+count+' 个候选，不会发送 WhatsApp'):'没有找到候选图片';}catch(err){$('matchNotice').textContent=err.message;$('matchNotice').classList.add('error');}});
$('settingsForm').addEventListener('submit',async e=>{e.preventDefault();$('settingsNotice').textContent='保存中…';try{await api('/api/product-image-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({auto_send_enabled:$('autoSend').value==='1',daily_limit:Number($('dailyLimit').value),customer_image_recognition_enabled:$('customerImageRecognition').checked,chat_product_image_enabled:$('chatProductImage').checked,marketing_product_image_enabled:$('marketingProductImage').checked,product_image_shadow_mode:$('shadowMode').checked,product_image_confidence_threshold:Number($('confidenceThreshold').value),product_image_cooldown_seconds:Number($('cooldownSeconds').value),product_image_global_kill_switch:$('globalKillSwitch').checked})});$('settingsNotice').textContent='已保存';}catch(err){$('settingsNotice').textContent=err.message;$('settingsNotice').classList.add('error');}});
$('uploadForm').addEventListener('submit',async e=>{e.preventDefault();const file=$('image').files[0];if(!file)return;const form=new FormData();form.set('title',$('title').value);form.set('tags',JSON.stringify($('tags').value.split(',').map(v=>v.trim()).filter(Boolean)));form.set('product_name',$('productName').value);form.set('sku',$('sku').value);form.set('aliases',JSON.stringify($('aliases').value.split(',').map(v=>v.trim()).filter(Boolean)));form.set('product_id',$('productId').value);form.set('variant',$('variant').value);form.set('reference_role',$('role').value);form.set('allow_visual_match',$('allowVisual').checked?'1':'0');form.set('allow_auto_send',$('allowAuto').checked?'1':'0');form.set('caption_template',$('caption').value);form.set('image',file);$('uploadNotice').textContent='上传中…';try{await api('/api/product-images',{method:'POST',body:form});$('uploadNotice').textContent='上传成功';e.target.reset();await load();}catch(err){$('uploadNotice').textContent=err.message;$('uploadNotice').classList.add('error');}});
$('productForm').addEventListener('submit',async e=>{e.preventDefault();$('catalogNotice').textContent='保存中…';try{const body={product_key:$('catalogKey').value.trim(),product_name:$('catalogName').value.trim(),sku:$('catalogSku').value.trim(),aliases:$('catalogAliases').value.split(',').map(v=>v.trim()).filter(Boolean),description:$('catalogDescription').value,allow_ai_image_send:$('catalogAiImage').checked,allow_marketing_image_send:$('catalogMarketingImage').checked};if(editingProduct)body.product_id=editingProduct;await api(editingProduct?('/api/product-catalog/'+encodeURIComponent(editingProduct)):'/api/product-catalog',{method:editingProduct?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('catalogNotice').textContent='已保存';editingProduct='';$('productForm').reset();$('catalogAiImage').checked=true;$('catalogMarketingImage').checked=true;await loadCatalog();}catch(err){$('catalogNotice').textContent=err.message;$('catalogNotice').classList.add('error');}});$('catalogReset').addEventListener('click',()=>{editingProduct='';$('productForm').reset();$('catalogAiImage').checked=true;$('catalogMarketingImage').checked=true;});
$('tagForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/product-tags',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({display_name:$('newTag').value})});$('newTag').value='';$('tagNotice').textContent='已新增';await load();}catch(err){$('tagNotice').textContent=err.message;$('tagNotice').classList.add('error');}});load().catch(e=>{$('assets').textContent=e.message;});
})();</script></body></html>'''


__all__ = ["product_image_page"]

